insert into public.profiles (id, name, age, sun, moon, rising, photo, aligns_back, founder, card, starter_day, starter_traded, blurb, deal_order, comet) values
  ('m24', 'Maya', 24, 'virgo', 'scorpio', 'cancer', 'img/people/p3.jpg', false, null, '{"initial":"Maya","serial":"№ 027","pull":"Slow burn","reading":[{"kind":"pull","text":"She notices the small stuff — and remembers it.","strength":3},{"kind":"push","text":"She plans, you go with the flow. Agree on plans early.","strength":2},{"kind":"align","text":"You both want steady. Easy to build a routine together.","strength":2}],"dealbreakers":"Late replies. Loud chewing. Anyone who hates dogs."}'::jsonb, null, false, 'ER nurse on nights. Alphabetised spice rack. Soft for dogs.', 0, false),
  ('r29', 'Rio', 29, 'leo', 'aries', 'sagittarius', 'img/people/p9.jpg', false, 18, '{"initial":"Rio","serial":"№ 029","pull":"Wild card","reading":[{"kind":"pull","text":"Warm and funny. A date with Rio feels like an event.","strength":3},{"kind":"push","text":"You’re both stubborn. Decide now who says sorry first.","strength":3},{"kind":"align","text":"Works if you take turns choosing what you do.","strength":1}],"dealbreakers":"Flaking on plans. Small talk forever. No sense of adventure."}'::jsonb, null, false, 'Chef at a supper club. I’ll feed you before I flirt.', 1, false),
  ('j27', 'Juniper', 27, 'libra', 'gemini', 'aquarius', 'img/juniper.jpg', true, null, '{"initial":"Juniper","serial":"№ 031","pull":"Rare pull","house":"7th house","reading":[{"kind":"pull","text":"Easy to talk to — it flows from the very first text.","strength":3},{"kind":"push","text":"She takes time to decide. Give her two options, not ten.","strength":2},{"kind":"align","text":"Same taste, same values. You’d host great dinners together.","strength":3}],"dealbreakers":"One-word texts. Refusing to talk it out the same night. Hating my group chats.","bio":"Gallery girl by day, playlist archivist by night. I read last pages first, cry at planetarium shows, and will absolutely rearrange your bookshelf by colour. Looking for someone who argues gently and means it.","religion":"Spiritual, not religious","lookingFor":"Long-term, open to slow","height":"5′6″","work":"Assistant curator","interests":["Film photography","Vinyl","Planetariums","Ceramics","Wine bars"]}'::jsonb, null, false, 'Assistant curator. Playlist archivist. Cries at planetariums.', 2, false),
  ('a31', 'Ari', 31, 'aquarius', 'libra', 'gemini', 'img/people/p6.jpg', false, null, '{"initial":"Ari","serial":"№ 033","pull":"Steady pull","reading":[{"kind":"pull","text":"Never boring. Every date is something new.","strength":2},{"kind":"push","text":"You like a plan; they like surprises. Trade off weekends.","strength":2},{"kind":"align","text":"They bring the ideas, you make them happen.","strength":2}],"dealbreakers":"Jealousy. Astrology skeptics. Bad playlists."}'::jsonb, 4, true, 'Builds synths. Will explain them if you ask once.', 3, false),
  ('s26', 'Sol', 26, 'pisces', 'cancer', 'scorpio', 'img/people/p7.jpg', false, null, '{"initial":"Sol","serial":"№ 036","pull":"Strong pull","reading":[{"kind":"pull","text":"Gentle, and easy to be quiet with.","strength":3},{"kind":"push","text":"They feel things fast; you need time. Say when you need space.","strength":1},{"kind":"align","text":"Calm, caring, slow to fight. Good for the long term.","strength":3}],"dealbreakers":"Coldness. Rushing. Never asking how my day was."}'::jsonb, null, false, 'Ceramicist. Bad at texting, great at long walks.', 4, false),
  ('k28', 'Kai', 28, 'capricorn', 'taurus', 'virgo', 'img/people/p2.jpg', false, null, '{"initial":"Kai","serial":"№ 038","pull":"Steady pull","reading":[{"kind":"pull","text":"Reliable. If Kai says 7, Kai is there at 7.","strength":2},{"kind":"push","text":"Two busy planners. Put fun on the calendar or it won’t happen.","strength":2},{"kind":"align","text":"Same goals, same pace. Built for the long run.","strength":3}],"dealbreakers":"Being late. Not having goals. Chaos for fun."}'::jsonb, null, false, 'Architect. Plans the whole trip, forgets the charger.', 5, false),
  ('l26', 'Lena', 26, 'gemini', 'aquarius', 'leo', 'img/people/p1.jpg', false, null, '{"initial":"Lena","serial":"№ 041","pull":"Wild card","reading":[{"kind":"pull","text":"Great texter. Flirty, quick, keeps you laughing.","strength":3},{"kind":"push","text":"She changes plans a lot. Lock in the ones that matter.","strength":2},{"kind":"align","text":"She keeps things light; you keep them grounded.","strength":2}],"dealbreakers":"Bad texters. Nowhere to dance. People who never ask a question back."}'::jsonb, null, false, 'Podcast producer. Three new hobbies a month, one keeper.', 6, false),
  ('a29', 'Amara', 29, 'sagittarius', 'leo', 'aries', 'img/people/p8.jpg', false, null, '{"initial":"Amara","serial":"№ 044","pull":"Strong pull","reading":[{"kind":"pull","text":"Confident. She’ll ask you out before you ask her.","strength":3},{"kind":"push","text":"She moves fast; you like to be sure. Say what pace works.","strength":3},{"kind":"align","text":"She brings the adventure, you bring the home base.","strength":2}],"dealbreakers":"Indecision. Cancelled plans. Anyone who can’t laugh at themselves."}'::jsonb, null, false, 'Flight attendant. Home for the weekend, maybe yours.', 7, false),
  ('t30', 'Theo', 30, 'cancer', 'virgo', 'virgo', 'img/people/p11.jpg', false, null, '{"initial":"Theo","serial":"№ 047","pull":"Steady pull","reading":[{"kind":"pull","text":"Thoughtful. Remembers how you take your coffee.","strength":3},{"kind":"push","text":"He needs to hear it. Say how you feel, even when it’s obvious.","strength":2},{"kind":"align","text":"Two homebodies. Cooking in beats going out.","strength":2}],"dealbreakers":"Coldness. Flaky plans. People who never call their mum."}'::jsonb, null, false, 'Teacher. Brings you soup when you’re sick, unasked.', 8, false),
  ('n27', 'Noor', 27, 'libra', 'gemini', 'gemini', 'img/people/p5.jpg', false, 77, '{"initial":"Noor","serial":"№ 049","pull":"Slow burn","reading":[{"kind":"pull","text":"Same taste in food, music and people.","strength":3},{"kind":"push","text":"She weighs every option; you’ve already picked. Meet halfway.","strength":2},{"kind":"align","text":"She brings the ideas, you bring the plan.","strength":2}],"dealbreakers":"Rudeness to waiters. One-word answers. Bad shoes."}'::jsonb, null, false, 'Interior designer. Will judge your couch, kindly.', 9, false),
  ('j28', 'Jae', 28, 'sagittarius', 'aries', 'aries', 'img/people/p4.jpg', false, null, '{"initial":"Jae","serial":"№ 052","pull":"Wild card","reading":[{"kind":"pull","text":"Spontaneous. Makes an ordinary Tuesday memorable.","strength":3},{"kind":"push","text":"He wants to travel; you want to stay. Plan one trip together.","strength":2},{"kind":"align","text":"Works if he explores and you’re the home he comes back to.","strength":2}],"dealbreakers":"Small talk. Closed minds. Anyone who hates travel."}'::jsonb, null, false, 'Photographer. Passport is always in the bag.', 10, false),
  ('b25', 'Bianca', 25, 'taurus', 'pisces', 'pisces', 'img/people/p10.jpg', false, null, '{"initial":"Bianca","serial":"№ 055","pull":"Strong pull","reading":[{"kind":"pull","text":"Same sign. You get each other without explaining.","strength":3},{"kind":"push","text":"Both stubborn. Pick your battles — and who picks dinner.","strength":2},{"kind":"align","text":"Slow, steady, loyal. Good food, little drama.","strength":2}],"dealbreakers":"Rushing. Cheap wine. Being late to dinner."}'::jsonb, null, false, 'Pastry chef. Up at 4am, asleep by 9, worth it.', 11, false),
  ('i24', 'Ivy', 24, 'pisces', 'taurus', 'taurus', 'img/people/p12.jpg', false, 203, '{"initial":"Ivy","serial":"№ 058","pull":"Steady pull","reading":[{"kind":"pull","text":"Picks up on your mood before you say a word.","strength":3},{"kind":"push","text":"She drifts; you like to decide. Don’t steamroll her.","strength":2},{"kind":"align","text":"Tender and patient. A strong long-term match.","strength":2}],"dealbreakers":"Cynics. Shouting. Anyone who laughs at horoscopes."}'::jsonb, null, false, 'Music therapist. Sings in the car, badly, on purpose.', 12, false),
  ('d31', 'Dev', 31, 'leo', 'libra', 'libra', 'img/people/p6.jpg', false, null, '{"initial":"Dev","serial":"№ 061","pull":"Wild card","reading":[{"kind":"pull","text":"Charming and bold. Never a dull night out.","strength":3},{"kind":"push","text":"He likes the spotlight; you like the good seat. Let him have it.","strength":2},{"kind":"align","text":"He brings the energy, you bring the consistency.","strength":2}],"dealbreakers":"Being ignored. Grey outfits. Leaving early."}'::jsonb, null, false, 'Stand-up on Thursdays. Fintech the rest of the week.', 13, false),
  ('r29b', 'Rosa', 29, 'gemini', 'cancer', 'cancer', 'img/people/p7.jpg', false, null, '{"initial":"Rosa","serial":"№ 064","pull":"Slow burn","reading":[{"kind":"pull","text":"Gets you talking, even on your quiet days.","strength":3},{"kind":"push","text":"She likes new; you like familiar. Take turns picking.","strength":2},{"kind":"align","text":"She keeps it moving, you keep it real.","strength":2}],"dealbreakers":"Boredom. Texting “k”. Anyone who won’t try the new place."}'::jsonb, null, false, 'Journalist. Asks one question too many. Sorry.', 14, false),
  ('e30', 'Elio', 30, 'aquarius', 'gemini', 'gemini', 'img/people/p2.jpg', false, null, '{"initial":"Elio","serial":"№ 071","pull":"Wild card","reading":[{"kind":"pull","text":"Unpredictable in a good way. Always has a new idea.","strength":3},{"kind":"push","text":"He’s on his phone a lot. Agree on phone-free dates.","strength":2},{"kind":"align","text":"He brings what’s new, you keep what’s good.","strength":2}],"dealbreakers":"Routine for its own sake. Phones at dinner (his own rule, he breaks it)."}'::jsonb, null, false, 'Game designer. Thinks in levels, texts in memes.', null, true),
  ('m27', 'Mina', 27, 'capricorn', 'scorpio', 'scorpio', 'img/people/p3.jpg', false, null, '{"initial":"Mina","serial":"№ 073","pull":"Strong pull","reading":[{"kind":"pull","text":"Direct. You’ll always know where you stand.","strength":3},{"kind":"push","text":"Two planners, few surprises. Someone has to be spontaneous.","strength":2},{"kind":"align","text":"Same goals, same work ethic. Built to last.","strength":2}],"dealbreakers":"Vagueness. Being late. People who won’t say what they want."}'::jsonb, null, false, 'Lawyer. Reads the fine print. Reads you too.', null, true),
